// The 10 test questions and their right answers (from test_questions.json)
const QUESTIONS = [
  {
    "question": "Which QuickBooks bookkeepers are Certified QuickBooks ProAdvisors with at least 5 years of bookkeeping experience?",
    "expected": [
      "Imran Siddiqui",
      "Ma. Teresa Gonzaga",
      "Rowena Castillo"
    ]
  },
  {
    "question": "Find GoHighLevel specialists with 3+ years of GHL experience who speak Arabic.",
    "expected": [
      "Karim Abdelrahman",
      "Lina Haddad",
      "Rami Khoury",
      "Youssef Benali"
    ]
  },
  {
    "question": "Which customer support agents have worked with Gorgias on a Shopify store?",
    "expected": [
      "Ahmed Shalaby",
      "Fernanda Lima",
      "Paolo Navarro"
    ]
  },
  {
    "question": "Find a bookkeeper who is a licensed CPA with 8+ years of NetSuite experience.",
    "expected": "NO_MATCH"
  },
  {
    "question": "Who has 3+ years of GoHighLevel and also builds automations in Make.com (Integromat)?",
    "expected": [
      "Bilal Qureshi",
      "Joanna Dimaculangan",
      "Lina Haddad"
    ]
  },
  {
    "question": "Which social media managers edit video in CapCut and have run TikTok Ads campaigns?",
    "expected": [
      "Daniela Quintero",
      "Hiba Saad",
      "Nicole Dela Cruz"
    ]
  },
  {
    "question": "Which customer support agents have used Kustomer?",
    "expected": [
      "Aisha Rahman",
      "Omar Haddadin"
    ]
  },
  {
    "question": "Who has migrated clients from Keap (Infusionsoft) to GoHighLevel?",
    "expected": "NO_MATCH"
  },
  {
    "question": "Which executive virtual assistants have worked directly for a CEO or founder and handle travel booking?",
    "expected": [
      "Camila Ortega",
      "Hannah Mwangi",
      "Kristine Joy Bautista"
    ]
  },
  {
    "question": "Find a GoHighLevel specialist who is fluent in German.",
    "expected": "NO_MATCH"
  }
];
return QUESTIONS.map(q => ({ json: { ...q, role_code: '' } }));

const qs = $('Questions').all().map(i => i.json);
const runAt = new Date().toISOString();
return $input.all().map((it, i) => {
  const q = qs[i], r = it.json;
  const got = (r.candidates || []).map(c => String(c.name).toLowerCase().trim()).sort();
  const exp = q.expected === 'NO_MATCH' ? [] : q.expected.map(n => n.toLowerCase().trim()).sort();
  const passed = JSON.stringify(got) === JSON.stringify(exp) && (r.candidates || []).every(c => c.cv_file);
  return { json: {
    question: q.question,
    expected: q.expected === 'NO_MATCH' ? 'No good match' : q.expected.join(', '),
    bot_answer: r.text || '',
    passed,
    run_at: runAt,
  } };
});

const rows = $('Grade').all().map(i => i.json);
return [{ json: { score: `${rows.filter(r => r.passed).length} / ${rows.length}`,
                  failed: rows.filter(r => !r.passed).map(r => r.question) } }];
